  "distractors": [  
    {  
      "text": "They unanimously support building the bridge to boost tourism and economic growth.",  
      "why_wrong": "This contradicts the text, which clearly states that there is strong opposition to the bridge due to environmental and cultural concerns, showing the islanders are not united in favor of the bridge."  
    },  
    {  
      "text": "They believe the ferry system is outdated and should be replaced entirely with a bridge.",  
      "why_wrong": "The text presents the ferry as a viable alternative, with some islanders advocating for upgrading it rather than replacing it, so claiming they believe it is outdated misrepresents their views."  
    },  
    {  
      "text": "They are eager to become a part of the mainland's urban sprawl and welcome increased development.",  
      "why_wrong": "The text highlights fears that a bridge would erode the island's unique identity and turn it into a suburb, indicating that many islanders resist becoming part of mainland urban expansion."  
    },  
    {  
      "text": "They have already decided to build the bridge because it is the only way to improve travel times.",  
      "why_wrong": "The text states the decision is still pending and that the community is debating options, so claiming a decision has already been made is factually incorrect based on the passage."  
    },  
    {  
      "text": "They are confident that the ferry upgrade will be funded and implemented without any challenges.",  
      "why_wrong": "The text explicitly says it is unclear whether an upgraded ferry is possible, depending on negotiations and funding, so assuming confidence in its success misrepresents the uncertainty described."  
    },  
    {  
      "text": "They view the bridge as a necessary step to preserve their traditional way of life.",  
      "why_wrong": "The text presents the bridge as a threat to tradition and identity, with critics fearing it would undermine the island’s uniqueness, so claiming it preserves tradition contradicts the central conflict in the passage."  
    }  
  ]  
}
